mapper.update:
update product_catalog_revision
set es_locked_by=null,es_locked_until=null,updated_at=current_timestamp(3)
where product_id=#{productId} and es_locked_by=#{token}

mapper.select:
select count(*)
from product_projection_task t
left join product_catalog_revision r on r.product_id=t.product_id
where t.id=#{id} and t.status='PROCESSING' and t.locked_by=#{token}
  and t.locked_until>#{requiredUntil}
  and (t.target<>'ES' or (r.es_locked_by=#{token} and r.es_locked_until>#{requiredUntil}))
